function renderThreads(filter='all',search=''){const data=threads.filter(t=>(filter==='all'||t.type===filter)&&`${t.name} ${t.preview}`.toLowerCase().includes(search.toLowerCase()));$('#threadList').innerHTML=data.map(t=>`<div class="thread" data-id="${t.id}"><span class="queue-avatar">${t.initials}</span><div class="thread-body"><strong>${t.name}</strong><small>${t.preview}</small>${t.type==='human'?'<em class="tag">Needs human</em>':t.type==='order'?'<em class="tag order">Order</em>':''}</div><time>${t.time}</time></div>`).join('');$$('.thread').forEach(x=>x.onclick=()=>openThread(+x.dataset.id))}
function openThread(id){const t=threads.find(x=>x.id===id);$$('.thread').forEach(x=>x.classList.toggle('active',+x.dataset.id===id));$('#conversation').innerHTML=`<div class="conversation-head"><div><strong>${t.name}</strong><small>Messenger · ${t.type==='human'?'Needs human review':'Automation active'}</small></div><button class="button ${t.type==='human'?'primary':'secondary'}" id="takeover">${t.type==='human'?'Take over':'Close thread'}</button></div><div class="messages">${t.messages.map(m=>`<div class="message ${m[0]==='out'?'out':''}"><div class="bubble">${m[1]}<small>${m[2]}</small></div></div>`).join('')}</div><form class="composer"><input aria-label="Reply message" placeholder="Write a reply…"><button class="button primary" type="submit"><span>Send</span></button></form>`;$('#customerPanel').innerHTML=`<div class="customer-card"><span class="queue-avatar">${t.initials}</span><h3>${t.name}</h3><p>Customer profile</p></div><div class="detail-list"><div><span>Phone</span><b>${t.phone}</b></div><div><span>Location</span><b>${t.city}</b></div><div><span>Orders</span><b>${t.type==='order'?1:2}</b></div><div><span>Channel</span><b>Messenger</b></div></div>`;$('#conversation').classList.add('mobile-open');$('.thread-list').classList.add('thread-open');$('.composer').onsubmit=e=>{e.preventDefault();const i=e.currentTarget.querySelector('input');if(!i.value.trim())return;t.messages.push(['out',i.value,'Now']);openThread(id);toast('Reply added to demo conversation')};$('#takeover').onclick=()=>toast(t.type==='human'?'Human takeover started':'Conversation closed')}
