function renderOrders(){const q=$('#orderSearch').value.toLowerCase(),s=$('#orderStatus').value;const data=orders.filter(o=>(s==='all'||o.status===s)&&Object.values(o).join(' ').toLowerCase().includes(q));$('#ordersTable').innerHTML=data.map(o=>`<tr><td><strong>${o.name}</strong><br><small>${o.phone}</small></td><td>${o.product}</td><td><strong>${o.total}</strong></td><td><span class="status-badge ${o.status}">${o.status[0].toUpperCase()+o.status.slice(1)}</span></td><td>${o.updated}</td></tr>`).join('')}
