function renderRules(){$('#ruleList').innerHTML=rules.map((r,i)=>`<article class="rule-card"><div><h3>${r.name}</h3><p>${r.reply}</p></div><div class="keyword">${r.keyword}</div><button class="toggle ${r.on?'on':''}" data-rule="${i}" aria-pressed="${r.on}"><i></i></button></article>`).join('');$$('[data-rule]').forEach(b=>b.onclick=()=>{const r=rules[+b.dataset.rule];r.on=!r.on;renderRules();toast(`${r.name} ${r.on?'enabled':'paused'}`)})}renderRules();
function renderFaq(){$('#faqGrid').innerHTML=faqs.map(f=>`<article class="faq-card"><h3>${f.q}</h3><p>${f.a}</p><div class="faq-meta"><span>${f.cat}</span><span>${f.hits} matches</span></div></article>`).join('')}renderFaq();
