function restoreSettingsValues(panel){panel.querySelectorAll('[name]:not([data-secret])').forEach(input=>{const saved=localStorage.getItem(`pagepilot:${panel.dataset.settingsForm}:${input.name}`);if(saved!==null)input.value=saved});panel.querySelectorAll('input[type="range"]').forEach(input=>{const out=input.closest('.range-row')?.querySelector('output');if(out)out.value=`${input.value}%`;input.oninput=()=>out.value=`${input.value}%`})}
function bindSettingsPanel(){settingsMain.querySelectorAll('.setting-toggle').forEach(toggle=>{const saved=localStorage.getItem(`pagepilot:${toggle.dataset.setting}`);if(saved!==null){const on=saved==='true';toggle.classList.toggle('on',on);toggle.setAttribute('aria-pressed',on)}toggle.onclick=()=>{const on=!toggle.classList.contains('on');toggle.classList.toggle('on',on);toggle.setAttribute('aria-pressed',on);localStorage.setItem(`pagepilot:${toggle.dataset.setting}`,on);toast(on?'Setting enabled':'Setting disabled')}});settingsMain.querySelectorAll('[data-settings-form]').forEach(form=>{restoreSettingsValues(form);const secret=form.querySelector('[data-secret]');if(secret){secret.addEventListener('copy',e=>{e.preventDefault();toast('API key copying is blocked')});secret.addEventListener('cut',e=>e.preventDefault());secret.addEventListener('dragstart',e=>e.preventDefault())}form.onsubmit=e=>{e.preventDefault();form.querySelectorAll('[name]:not([data-secret])').forEach(input=>localStorage.setItem(`pagepilot:${form.dataset.settingsForm}:${input.name}`,input.value));if(secret?.value.trim()){const state=form.querySelector('.secret-state');secret.value='';secret.blur();state.textContent='Configured';state.classList.add('configured');toast('API key accepted for this demo session and cleared')}else toast('Settings saved in this browser')}})}
